def run_fs(ops):
    # your code
    pass

practice.solution:
def run_fs(ops):
    files = {}
    for op, path, data in ops:
        if op == 'write':
            files[path] = data
        elif op == 'rm' and path in files:
            del files[path]
    dirs = set()
    for p in files:
        parts = p.split('/')
        cur = ''
        for part in parts[1:-1]:
            cur += '/' + part
            dirs.add(cur)
    return sorted(dirs)

