practice.solution:
def list_dir(paths, dir):
    prefix = dir
    if not prefix.endswith('/'):
        prefix += '/'
    names = set()
    for p in paths:
        if p.startswith(prefix):
            rest = p[len(prefix):]
            names.add(rest.split('/')[0])
    return sorted(names)

