practice.solution:
def run_chain(steps):
    ran = []
    last = 0
    for i in range(len(steps)):
        op, code = steps[i]
        go = False
        if op == '':
            go = True
        elif op == '&&':
            go = last == 0
        elif op == '||':
            go = last != 0
        if go:
            ran.append(i)
            last = code
    return ran

