def bind(sql, params):
    out = ''
    i = 0
    for ch in sql:
        if ch == '?':
            v = params[i]
            i += 1
            if isinstance(v, str):
                out += "'" + v.replace("'", "''") + "'"
            else:
                out += str(v)
        else:
            out += ch
    return out

