practice.solution:
import math
def cosine(a, b):
    d = 0.0
    na = 0.0
    nb = 0.0
    for x, y in zip(a, b):
        d += x * y
        na += x * x
        nb += y * y
    return round(d / (math.sqrt(na) * math.sqrt(nb)), 6)

practice.starter:
def fuse(a, b, k):
    # your code
    pass

practice.solution:
def fuse(a, b, k):
    score = {}
    order = []
    for lst in (a, b):
        for i in range(len(lst)):
            x = lst[i]
            if x not in score:
                score[x] = 0.0
                order.append(x)
            score[x] += 1.0 / (k + i + 1)
    ranked = sorted(range(len(order)), key=lambda j: (-round(score[order[j]], 12), j))
    return [order[j] for j in ranked]

