def compact(messages, limit, keep):
    total = 0
    for m in messages:
        total += len(m)
    if total <= limit:
        return messages
    n = len(messages) - keep
    if n <= 0:
        return messages
    return ['summary of ' + str(n) + ' messages'] + messages[n:]

