    # your code
    pass

practice.solution:
def field_matches(field, value):
    for part in field.split(','):
        if part == '*':
            return True
        if part.startswith('*/'):
            if value % int(part[2:]) == 0:
                return True
        elif '-' in part:
            a, b = part.split('-')
            if int(a) <= value <= int(b):
                return True
        elif int(part) == value:
            return True
    return False

