    # your code
    pass

practice.solution:
def run_tasks(cmds):
    tasks = []
    nid = 1
    for c, a in cmds:
        if c == 'add':
            tasks.append([nid, a, 'pending'])
            nid += 1
        elif c == 'start' or c == 'done':
            for t in tasks:
                if t[0] == a:
                    t[2] = 'active' if c == 'start' else 'done'
        elif c == 'clear':
            tasks = [t for t in tasks if t[2] != 'done']
    return tasks

