def run_queue(tasks, per_hour, quiet, hour):
    # your code
    pass

practice.solution:
def run_queue(tasks, per_hour, quiet, hour):
    if quiet:
        return []
    left = per_hour
    out = []
    for name, steps in tasks:
        if steps <= left:
            out.append(name)
            left -= steps
    return out
